    cycle_length = 0

    def dfs(node, parent):
        nonlocal cycle_length
        visited[node] = True
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if visited[neighbor]:
                cycle_length = len(graph[node])
                return True
